    <ellipse cx="420" cy="470" rx="330" ry="28" fill="#000" opacity=".08"/>
    ${DRAW[viewId](colors)}
  </svg>`
  return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`
}
