  gap: 4px;
  border: 0;
  padding: 0;
  margin: 0;
}

.field label,
.field legend {
  font-weight: 600;
  padding: 0;
}

.field input[type='number'] {
  width: 160px;
  height: 44px;
  padding: 0 10px;
  font: inherit;
  border: 1px solid var(--ink);
  border-radius: 4px;
}

.radio {
  display: inline-flex !important;
  align-items: center;
  gap: 8px;
  min-height: 44px;
  font-weight: 400 !important;
  margin-right: 12px;
}

.radio input {
  width: 20px;
  height: 20px;
  accent-color: var(--brand);
}

.size-result {
  font-size: 1.1rem;
  font-weight: 700;
  flex-basis: 100%;
}

.size-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.95rem;
}

.size-table caption {
  text-align: left;
  font-weight: 700;
  margin-bottom: 8px;
}

.size-table th,
.size-table td {
  padding: 8px;
  border-bottom: 1px solid var(--line);
  text-align: left;
}

/* More information tabs */
.info-section {
  margin-top: 56px;
}

.info-section > h2,
.faq > h2 {
  font-size: 1.5rem;
  margin-bottom: 16px;
}

.tablist {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  border-bottom: 1px solid var(--line);
}

.tab {
  min-height: 44px;
  padding: 10px 18px;
  background: none;
  border: 0;
  border-bottom: 3px solid transparent;
  font: inherit;
  color: var(--muted);
  cursor: pointer;
}

.tab[aria-selected='true'] {
  color: var(--ink);
  font-weight: 700;
  border-bottom-color: var(--ink);
}

.tabpanel {
  padding: 24px 4px;
  max-width: 760px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.tabpanel[hidden] {
  display: none;
}

.spec-list {
  margin: 0;
  display: grid;
  gap: 12px;
}

.spec-list div {
  display: grid;
  grid-template-columns: 200px 1fr;
  gap: 16px;
  border-bottom: 1px solid var(--line);
  padding-bottom: 8px;
}

.spec-list dt {
  font-weight: 600;
}

.spec-list dd {
  margin: 0;
}

.review-list {
  margin: 0;
  padding: 0;
  list-style: none;
  display: grid;
  gap: 16px;
}

.review-list li {
  border-left: 3px solid var(--line);
  padding-left: 12px;
}

/* Questions */
.faq {
  margin-top: 48px;
  max-width: 760px;
}

.faq-item {
  border-bottom: 1px solid var(--line);
}

.faq h3 {
  font-size: 1rem;
}

.faq-question {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  width: 100%;
  min-height: 48px;
  padding: 12px 4px;
  background: none;
  border: 0;
  font: inherit;
  font-weight: 600;
  text-align: left;
  color: var(--ink);
  cursor: pointer;
}

.faq-icon {
  font-size: 1.4rem;
  line-height: 1;
}

.faq-answer {
  padding: 0 4px 16px;
}

.faq-answer[hidden] {
  display: none;
}

/* Footer */
.site-footer {
  margin-top: 64px;
  padding: 40px 0 24px;
  background: var(--surface);
  border-top: 1px solid var(--line);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 32px;
}

.site-footer h2 {
  font-size: 1rem;
  margin-bottom: 12px;
}

.footer-list {
  margin: 0;
  padding: 0;
  list-style: none;
  display: grid;
  gap: 4px;
}

.footer-list a {
  display: inline-block;
  min-height: 32px;
  padding: 4px 0;
  color: var(--ink);
}

.copyright {
  margin-top: 32px;
  color: var(--muted);
  font-size: 0.9rem;
}

@media (prefers-reduced-motion: reduce) {
  .pp * {
    transition: none !important;
    animation: none !important;
  }
}
EOF
